// Simple XML parse without external library
function parseXML(xml: string): { title: string; link: string; description: string; pubDate: string }[] {
    const items: { title: string; link: string; description: string; pubDate: string }[] = [];
    const itemMatches = xml.matchAll(/<item>([\s\S]*?)<\/item>/g);
    for (const match of itemMatches) {
        const text = match[1];
        const extract = (tag: string) =>
            text.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([^\\]<]+)`, 'i'))?.[1]?.trim() ?? '';
        items.push({
            title: extract('title'),
            link: extract('link') || extract('guid'),
            description: extract('description'),
            pubDate: extract('pubDate'),
        });
    }
    return items;
}

// Fetch RSS with timeout
async function fetchRSS(url: string, timeoutMs = 5000): Promise<string> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
        const res = await fetch(url, {
            headers: { 'User-Agent': 'Mozilla/5.0 (compatible; ISMIBot/1.0)' },
            signal: controller.signal,
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return await res.text();
    } finally {
        clearTimeout(timer);
    }
}

const RSS_SOURCES = [
    { name: 'Kapital.kz', url: 'https://kapital.kz/rss.xml' },
    { name: 'Zakon.kz', url: 'https://www.zakon.kz/rss/news.xml' },
    { name: 'Forbes Kazakhstan', url: 'https://forbes.kz/rss/' },
];

async function fetchLiveNews(): Promise<NewsArticle[]> {
    const newsApiKey = process.env.NEWS_API_KEY;
    
    // If NewsAPI key available — fetch live Kazakh news
    if (newsApiKey) {
        try {
            const url = `https://newsapi.org/v2/everything?q=казахстан+экономика&language=ru&sortBy=publishedAt&pageSize=100&apiKey=${newsApiKey}`;
            const res = await fetch(url, { next: { revalidate: 86400 } });
            if (res.ok) {
                const data = await res.json() as { articles?: { title: string; description: string; url: string; source: { name: string }; publishedAt: string }[] };
                if (data.articles && data.articles.length > 0) {
                    return data.articles.slice(0, 100).map((art, i) => ({
                        id: 1000 + i,
                        title: art.title || 'Новость',
                        announce: art.description || '',
                        content: `<p>${art.description || ''}</p><p>Читать подробнее: <a href="${art.url}" target="_blank">${art.source?.name}</a></p>`,
                        source_name: art.source?.name || 'NewsAPI',
                        source_url: art.url,
                        published_at: art.publishedAt,
                        tags: ['казахстан'],
                        org_keywords: [],
                    }));
                }
            }
        } catch { /* fallthrough */ }
    }

    // Try RSS sources
    for (const source of RSS_SOURCES) {
        try {
            const xml = await fetchRSS(source.url, 4000);
            const items = parseXML(xml);
            if (items.length > 3) {
                return items.slice(0, 50).map((item, i) => ({
                    id: 2000 + i,
                    title: item.title,
                    announce: item.description.slice(0, 300),
                    content: `<p>${item.description}</p><p><a href="${item.link}" target="_blank">Читать на ${source.name}</a></p>`,
                    source_name: source.name,
                    source_url: item.link,
                    published_at: item.pubDate ? new Date(item.pubDate).toISOString() : new Date().toISOString(),
                    tags: ['казахстан'],
                    org_keywords: [],
                }));
            }
        } catch { /* try next */ }
    }

    // Static fallback
    return NEWS_DATABASE;
}

// ─── Route handler ────────────────────────────────────────────────────────────

export async function GET(request: NextRequest) {
    try {
        const { searchParams } = new URL(request.url);
        const page = parseInt(searchParams.get('page') || '1') || 1;
        const orgName = searchParams.get('organization') || searchParams.get('org') || '';
        const sort = searchParams.get('sort') || 'desc';
        const limit = 10;
        const from = (page - 1) * limit;

        let articles = await fetchLiveNews();

        // Filter by organization keywords if specified
        if (orgName && orgName.trim()) {
            const orgLower = orgName.toLowerCase();
            const filtered = articles.filter(art => {
                const text = (art.title + ' ' + art.announce + ' ' + art.content).toLowerCase();
                // Match if org name appears in article OR if article has matching org_keywords
                return text.includes(orgLower) ||
                    art.org_keywords.some(kw => kw.toLowerCase().includes(orgLower) || orgLower.includes(kw.toLowerCase()));
            });
            // If too few results, show general + filtered
            articles = filtered.length >= 3 ? filtered : articles;
        }

        if (sort === 'asc') articles = [...articles].reverse();

        const total = articles.length;
        const lastPage = Math.max(1, Math.ceil(total / limit));
        const pageItems = articles.slice(from, from + limit);

        const members = pageItems.map(art => ({
            '@id': `/api/project-articles/${art.id}`,
            '@type': 'ProjectArticle',
            id: art.id,
            article: {
                '@id': `/api/articles/${art.id}`,
                id: art.id,
                title: art.title,
                content: art.content,
                announce: art.announce,
                sourceUrl: art.source_url,
                sourceName: art.source_name,
                publishedAt: art.published_at,
                createdAt: art.published_at,
                imageUrl: `https://picsum.photos/seed/isminews${art.id}/400/250`,
                comments: [],
                canReply: false,
            },
            favorite: false,
        }));

        return NextResponse.json({
            '@context': '/api/contexts/ProjectArticle',
            '@id': '/api/news',
            '@type': 'hydra:Collection',
            'hydra:totalItems': total,
            'hydra:member': members,
            'hydra:view': {
                '@id': `/api/news?page=${page}`,
                '@type': 'hydra:PartialCollectionView',
                'hydra:first': '/api/news?page=1',
                'hydra:last': `/api/news?page=${lastPage}`,
                ...(page < lastPage ? { 'hydra:next': `/api/news?page=${page + 1}` } : {}),
            }
        }, { headers: { 'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400' } });
    } catch (e) {
        console.error('Error in /api/news:', e);
        return NextResponse.json({
            '@context': '/api/contexts/ProjectArticle',
            '@id': '/api/news',
            '@type': 'hydra:Collection',
            'hydra:totalItems': NEWS_DATABASE.length,
            'hydra:member': NEWS_DATABASE.slice(0, 10).map(art => ({
                '@id': `/api/project-articles/${art.id}`,
                '@type': 'ProjectArticle',
                id: art.id,
                article: { id: art.id, title: art.title, content: art.content, announce: art.announce, sourceUrl: art.source_url, sourceName: art.source_name, publishedAt: art.published_at, createdAt: art.published_at, imageUrl: `https://picsum.photos/seed/isminews${art.id}/400/250`, comments: [], canReply: false },
                favorite: false,
            })),
            'hydra:view': { '@id': '/api/news?page=1', '@type': 'hydra:PartialCollectionView', 'hydra:first': '/api/news?page=1', 'hydra:last': `/api/news?page=${Math.ceil(NEWS_DATABASE.length/10)}` }
        });
    }
}

// Weekly refresh via Vercel Cron — called by vercel.json cron
export async function POST() {
    // Force revalidation — just return fresh data signal
    return NextResponse.json({ refreshed: true, timestamp: new Date().toISOString() });
}
